"""Recursive-descent parser for the minisql SELECT grammar.

``parse(sql)`` returns a :class:`minisql.ast.Query`.  Every expression node
gets its ``text`` attribute set to the exact source substring it came from,
including surrounding parentheses when the whole expression was parenthesised.

The parser performs no semantic validation: table/column existence, function
arity, aggregate placement and grouping are checked by later stages.
"""

from typing import List, Optional, Tuple

from .ast import (
    Between,
    Binary,
    Column,
    Expr,
    Func,
    InList,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    SelectItem,
    Star,
    Unary,
)
from .errors import QueryError
from .lexer import EOF, IDENT, NUMBER, PUNCT, STRING, Token, tokenize

#: Words that may not be used as bare (unquoted) names.  Function names are
#: intentionally not reserved: ``count`` can still name a column.
KEYWORDS = frozenset(
    {
        "SELECT",
        "DISTINCT",
        "FROM",
        "WHERE",
        "GROUP",
        "BY",
        "HAVING",
        "ORDER",
        "LIMIT",
        "OFFSET",
        "AS",
        "ASC",
        "DESC",
        "AND",
        "OR",
        "NOT",
        "IS",
        "NULL",
        "IN",
        "BETWEEN",
        "LIKE",
        "TRUE",
        "FALSE",
    }
)

COMPARISON_OPERATORS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})
_SPECIAL_KEYWORDS = ("IN", "BETWEEN", "LIKE")


class _Parser:
    def __init__(self, sql: str) -> None:
        self.sql = sql
        self.tokens = tokenize(sql)
        self.index = 0

    # ------------------------------------------------------------------
    # Token helpers

    def _peek(self, offset: int = 0) -> Token:
        index = self.index + offset
        if index >= len(self.tokens):
            index = len(self.tokens) - 1
        return self.tokens[index]

    def _advance(self) -> Token:
        token = self.tokens[self.index]
        if token.kind != EOF:
            self.index += 1
        return token

    @staticmethod
    def _is_kw(token: Token, word: str) -> bool:
        return (
            token.kind == IDENT
            and not token.quoted
            and token.value.upper() == word
        )

    def _check_kw(self, word: str, offset: int = 0) -> bool:
        return self._is_kw(self._peek(offset), word)

    def _match_kw(self, word: str) -> bool:
        if self._check_kw(word):
            self._advance()
            return True
        return False

    def _expect_kw(self, word: str) -> Token:
        if not self._check_kw(word):
            self._error("expected %s, found %s" % (word, self._found(self._peek())))
        return self._advance()

    def _check_punct(self, value: str, offset: int = 0) -> bool:
        token = self._peek(offset)
        return token.kind == PUNCT and token.value == value

    def _match_punct(self, value: str) -> bool:
        if self._check_punct(value):
            self._advance()
            return True
        return False

    def _expect_punct(self, value: str) -> Token:
        if not self._check_punct(value):
            self._error("expected %r, found %s" % (value, self._found(self._peek())))
        return self._advance()

    # ------------------------------------------------------------------
    # Diagnostics

    def _found(self, token: Token) -> str:
        if token.kind == EOF:
            return "end of query"
        return repr(self.sql[token.start:token.end])

    def _error(self, message: str, token: Optional[Token] = None) -> "None":
        token = token if token is not None else self._peek()
        line = self.sql.count("\n", 0, token.start) + 1
        line_start = self.sql.rfind("\n", 0, token.start) + 1
        column = token.start - line_start + 1
        raise QueryError(
            "syntax error at line %d, column %d: %s" % (line, column, message)
        )

    # ------------------------------------------------------------------
    # Source spans and expression text

    def _mark(self, node: Expr, start: int, end: int) -> Expr:
        node.text = self.sql[start:end]
        node._start = start  # type: ignore[attr-defined]
        node._end = end  # type: ignore[attr-defined]
        return node

    @staticmethod
    def _start(node: Expr) -> int:
        return node._start  # type: ignore[attr-defined]

    @staticmethod
    def _end(node: Expr) -> int:
        return node._end  # type: ignore[attr-defined]

    def _binary(self, op: str, left: Expr, right: Expr) -> Expr:
        return self._mark(Binary(op, left, right), self._start(left), self._end(right))

    # ------------------------------------------------------------------
    # Statement

    def parse(self) -> Query:
        if self._peek().kind == EOF:
            self._error("empty query")

        self._expect_kw("SELECT")
        distinct = self._match_kw("DISTINCT")
        columns = self._parse_select_list()
        self._expect_kw("FROM")
        table = self._parse_name("table name")

        where: Optional[Expr] = None
        if self._match_kw("WHERE"):
            where = self._parse_expr()

        group_by: List[Expr] = []
        if self._match_kw("GROUP"):
            self._expect_kw("BY")
            group_by = self._parse_expr_list()

        having: Optional[Expr] = None
        if self._match_kw("HAVING"):
            having = self._parse_expr()

        order_by: List[OrderItem] = []
        if self._match_kw("ORDER"):
            self._expect_kw("BY")
            order_by = self._parse_order_list()

        limit: Optional[int] = None
        offset = 0
        if self._match_kw("LIMIT"):
            limit = self._parse_nonneg_int("LIMIT")
            if self._match_kw("OFFSET"):
                offset = self._parse_nonneg_int("OFFSET")
        elif self._match_kw("OFFSET"):
            # Permitted for convenience: OFFSET without LIMIT.
            offset = self._parse_nonneg_int("OFFSET")

        self._match_punct(";")
        if self._peek().kind != EOF:
            self._error(
                "unexpected %s after end of query" % self._found(self._peek())
            )

        return Query(
            columns=columns,
            table=table,
            distinct=distinct,
            where=where,
            group_by=group_by,
            having=having,
            order_by=order_by,
            limit=limit,
            offset=offset,
        )

    def _parse_name(self, what: str) -> str:
        token = self._peek()
        if token.kind != IDENT:
            self._error("expected %s, found %s" % (what, self._found(token)))
        if not token.quoted and token.value.upper() in KEYWORDS:
            self._error(
                "reserved keyword %r cannot be used as a bare %s; "
                "double-quote it to use it as a name"
                % (token.value.upper(), what),
                token,
            )
        self._advance()
        return token.value

    def _parse_nonneg_int(self, clause: str) -> int:
        token = self._peek()
        if token.kind != NUMBER or not isinstance(token.value, int):
            self._error(
                "expected a non-negative integer after %s, found %s"
                % (clause, self._found(token))
            )
        if token.value < 0:
            self._error("%s must be non-negative" % clause, token)
        self._advance()
        return token.value

    # ------------------------------------------------------------------
    # Select list and ORDER BY

    def _parse_select_list(self) -> List[SelectItem]:
        if self._check_punct("*"):
            token = self._advance()
            star = self._mark(Star(), token.start, token.end)
            if not self._check_kw("FROM"):
                self._error(
                    "SELECT * must be the only select item; "
                    "found %s after it" % self._found(self._peek())
                )
            return [SelectItem(star)]

        items: List[SelectItem] = []
        while True:
            expr = self._parse_expr()
            alias: Optional[str] = None
            if self._match_kw("AS"):
                alias = self._parse_name("alias")
            else:
                token = self._peek()
                if token.kind == IDENT and (
                    token.quoted or token.value.upper() not in KEYWORDS
                ):
                    alias = token.value
                    self._advance()
            items.append(SelectItem(expr, alias))
            if not self._match_punct(","):
                break
            if self._peek().kind == EOF:
                self._error("expected a column after ','")
        return items

    def _parse_expr_list(self) -> List[Expr]:
        exprs = [self._parse_expr()]
        while self._match_punct(","):
            exprs.append(self._parse_expr())
        return exprs

    def _parse_order_list(self) -> List[OrderItem]:
        items: List[OrderItem] = []
        while True:
            expr = self._parse_expr()
            desc = False
            if self._match_kw("DESC"):
                desc = True
            else:
                self._match_kw("ASC")
            items.append(OrderItem(expr, desc))
            if not self._match_punct(","):
                break
        return items

    # ------------------------------------------------------------------
    # Expressions, lowest to highest precedence

    def _parse_expr(self) -> Expr:
        return self._parse_or()

    def _parse_or(self) -> Expr:
        left = self._parse_and()
        while self._match_kw("OR"):
            right = self._parse_and()
            left = self._binary("OR", left, right)
        return left

    def _parse_and(self) -> Expr:
        left = self._parse_not()
        while self._match_kw("AND"):
            right = self._parse_not()
            left = self._binary("AND", left, right)
        return left

    def _parse_not(self) -> Expr:
        token = self._peek()
        if self._check_kw("NOT"):
            self._advance()
            operand = self._parse_not()
            node = Unary("NOT", operand)
            return self._mark(node, token.start, self._end(operand))
        return self._parse_comparison()

    def _parse_comparison(self) -> Expr:
        left = self._parse_additive()
        token = self._peek()

        if token.kind == PUNCT and token.value in COMPARISON_OPERATORS:
            self._advance()
            right = self._parse_additive()
            return self._binary(token.value, left, right)

        if self._check_kw("IS"):
            self._advance()
            negated = self._match_kw("NOT")
            if not self._match_kw("NULL"):
                self._error(
                    "expected NULL after IS%s, found %s"
                    % (" NOT" if negated else "", self._found(self._peek()))
                )
            null_token = self.tokens[self.index - 1]
            node = IsNull(left, negated)
            return self._mark(node, self._start(left), null_token.end)

        negated = False
        if self._check_kw("NOT") and any(
            self._check_kw(word, 1) for word in _SPECIAL_KEYWORDS
        ):
            self._advance()
            negated = True

        if self._check_kw("IN"):
            self._advance()
            self._expect_punct("(")
            items = [self._parse_expr()]
            while self._match_punct(","):
                items.append(self._parse_expr())
            close = self._expect_punct(")")
            node = InList(left, items, negated)
            return self._mark(node, self._start(left), close.end)

        if self._check_kw("BETWEEN"):
            self._advance()
            low = self._parse_additive()
            self._expect_kw("AND")
            high = self._parse_additive()
            node = Between(left, low, high, negated)
            return self._mark(node, self._start(left), self._end(high))

        if self._check_kw("LIKE"):
            self._advance()
            pattern = self._parse_additive()
            node = Like(left, pattern, negated)
            return self._mark(node, self._start(left), self._end(pattern))

        return left

    def _parse_additive(self) -> Expr:
        left = self._parse_multiplicative()
        while True:
            token = self._peek()
            if token.kind == PUNCT and token.value in ("+", "-", "||"):
                self._advance()
                right = self._parse_multiplicative()
                left = self._binary(token.value, left, right)
            else:
                return left

    def _parse_multiplicative(self) -> Expr:
        left = self._parse_unary()
        while True:
            token = self._peek()
            if token.kind == PUNCT and token.value in ("*", "/"):
                self._advance()
                right = self._parse_unary()
                left = self._binary(token.value, left, right)
            else:
                return left

    def _parse_unary(self) -> Expr:
        token = self._peek()
        if token.kind == PUNCT and token.value == "-":
            self._advance()
            operand = self._parse_unary()
            node = Unary("-", operand)
            return self._mark(node, token.start, self._end(operand))
        return self._parse_primary()

    def _parse_primary(self) -> Expr:
        token = self._peek()

        if token.kind == NUMBER:
            self._advance()
            return self._mark(Literal(token.value), token.start, token.end)

        if token.kind == STRING:
            self._advance()
            return self._mark(Literal(token.value), token.start, token.end)

        if token.kind == PUNCT and token.value == "(":
            open_token = self._advance()
            inner = self._parse_expr()
            close = self._expect_punct(")")
            # The node's text includes the parentheses exactly as written.
            return self._mark(inner, open_token.start, close.end)

        if token.kind == IDENT:
            if not token.quoted:
                upper = token.value.upper()
                if upper == "NULL":
                    self._advance()
                    return self._mark(Literal(None), token.start, token.end)
                if upper == "TRUE":
                    self._advance()
                    return self._mark(Literal(True), token.start, token.end)
                if upper == "FALSE":
                    self._advance()
                    return self._mark(Literal(False), token.start, token.end)
                if upper in KEYWORDS:
                    self._error("unexpected keyword %s" % upper, token)

            self._advance()
            if not token.quoted and self._check_punct("("):
                return self._parse_function(token)
            return self._mark(Column(token.value), token.start, token.end)

        self._error("expected an expression, found %s" % self._found(token))

    def _parse_function(self, name_token: Token) -> Expr:
        self._expect_punct("(")
        args: List[Expr] = []
        star = False

        if self._check_punct("*"):
            self._advance()
            close = self._expect_punct(")")
            star = True
        elif self._check_punct(")"):
            close = self._advance()
        else:
            args = [self._parse_expr()]
            while self._match_punct(","):
                args.append(self._parse_expr())
            close = self._expect_punct(")")

        node = Func(name_token.value.upper(), args, star)
        return self._mark(node, name_token.start, close.end)


def parse(sql: str) -> Query:
    """Parse one ``SELECT`` statement, raising ``QueryError`` on any problem."""
    return _Parser(sql).parse()
